import unittest,re
from tools.kjv_archive import load_register,read
class LukeRefusedShelterTests(unittest.TestCase):
 def test_refused_shelter_and_difficult_invitation(self):
  prior,_=load_register('0.10-kjv.206');lang,manifest=load_register('0.10-kjv.207')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('luke-'):c for c in read(lang.folder/'luke-refused-shelter-and-difficult-invitation-cases.json')};self.assertEqual(len(cases),70)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'13:1': ['kjv_galilaean_mark:pl', 'blood kjv_pilate', 'their/kjv_sacrifice mix'], '13:2': ['above all kjv_galilaean_mark:pl', 'sin:ag:pl', 'because such thing:pl suffer'], '13:3': ['ipl to you tell:pr no', 'unless repent', 'all likewise perish'], '13:4': ['twelve and six', 'kjv_tower in kjv_siloam_luke', 'kjv_jerusalem', 'sin:ag:pl'], '13:5': ['ipl to you tell:pr no', 'unless repent', 'all likewise perish'], '13:6': ['fig kjv_tree', 'his/kjv_vineyard', 'fruit', 'none find'], '13:7': ['kjv_vinedresser', 'three year:pl i', 'none find', 'down cut', 'ground burden'], '13:8': ['this year also', 'i around it kjv_dig', 'kjv_dung to it give'], '13:9': ['if fruit bring', 'if not', 'thou it down cut'], '13:10': ['kjv_sabbath', 'one_num of kjv_synagogue:pl'], '13:11': ['spirit of infirmity twelve and six year:pl', 'bend:psv', 'herself up lift', 'able:neg'], '13:12': ['woman from thine/infirmity loose'], '13:13': ['his/hand:pl lay', 'immediately straight', 'god glorify'], '13:14': ['ruler of kjv_synagogue', 'indignation', 'six day:pl', 'not on kjv_sabbath'], '13:15': ['thou kjv_hypocrite', 'his/ox or his/ass', 'kjv_animal_stall', 'water drink:inf'], '13:16': ['daughter of kjv_abraham', 'kjv_satan_temptation bind', 'twelve and six year:pl', 'this bond', 'kjv_sabbath'], '13:17': ['all his/kjv_adversary:pl ashamed', 'all people', 'glorious thing:pl'], '13:18': ['kingdom of god', 'ipl it compare'], '13:19': ['mustard seed', 'his/kjv_garden', 'great kjv_tree become', 'bird:pl of air', 'branch:pl lodge'], '13:20': ['again', 'kingdom of god', 'ipl compare'], '13:21': ['woman', 'three kjv_measure_portion:pl of kjv_flour', 'whole kjv_leaven'], '13:22': ['city:pl and village:pl', 'teach', 'kjv_jerusalem journey'], '13:23': ['few who save', 'to they say'], '13:24': ['narrow gate', 'ipl to you', 'seek:fu and able:neg'], '13:25': ['once master of house', 'door shut', 'lord lord to wesg open', 'i you from where', 'know:neg'], '13:26': ['wesg in thy/presence eat', 'drink', 'ourone/street:pl'], '13:27': ['i to you tell', 'i you from where', 'from i depart', 'kjv_iniquity'], '13:28': ['weep:ev and tooth:pl kjv_gnash', 'kjv_abraham and kjv_isaac and kjv_jacob', 'all prophet:pl', 'yourselves out thrust'], '13:29': ['from east', 'from west', 'from kjv_north', 'from kjv_south', 'down sit'], '13:30': ['last who first', 'first who last'], '13:31': ['same day', 'kjv_pharisee:pl', 'kjv_herod_tetrarch thou:a kill'], '13:32': ['that fox', 'ipl devil:pl', 'ipl today and tomorrow', 'third day ipl perfect'], '13:33': ['ipl today and tomorrow and following day', 'prophet outside kjv_jerusalem perish', 'able:neg'], '13:34': ['kjv_jerusalem kjv_jerusalem', 'with stone:pl kill', 'ipl thy/child:pl', 'hen her/young bird:pl', 'under her/wing:pl', 'you will:neg'], '13:35': ['your/house', 'kjv_desolate', 'ipl:a see:neg', 'until time', 'name of lord'], '14:1': ['one_num of chief kjv_pharisee:pl', 'bread eat', 'kjv_sabbath day', 'watch'], '14:2': ['man who dropsy'], '14:3': ['lawyer:pl and kjv_pharisee:pl', 'kjv_sabbath day heal:inf lawful'], '14:4': ['silent', 'take:pa and heal', 'go:inf allow'], '14:5': ['ass or ox into kjv_pit', 'kjv_sabbath', 'immediately', 'out pull:neg'], '14:6': ['answer:inf able:neg'], '14:7': ['call:psv', 'chief place:pl choose', 'see'], '14:8': ['wedding', 'highest place', 'more honourable'], '14:9': ['this man place give', 'with shame lowest place'], '14:10': ['lowest place', 'friend higher up go', 'honour', 'at meal'], '14:11': ['himself kjv_exalt', 'low make', 'himself humble', 'kjv_exalt:psv'], '14:12': ['dinner or supper', 'thy/friend:pl', 'thy/brother:pl', 'thy/kinsman:pl', 'thy/rich neighbour:pl', 'recompense'], '14:13': ['poor person:pl', 'kjv_maimed person:pl', 'kjv_lame person:pl', 'blind person:pl'], '14:14': ['recompense:inf able:neg', 'kjv_resurrection of kjv_righteous'], '14:15': ['one_num of they', 'bread eat', 'kingdom of god'], '14:16': ['certain man', 'great supper', 'many call'], '14:17': ['supper time', 'his/servant', 'all thing:pl now ready'], '14:18': ['one_num consent', 'first', 'i piece of ground buy', 'i it see', 'i:a excuse'], '14:19': ['i five yoke:pl of ox:pl', 'i they:a test', 'i:a excuse'], '14:20': ['i wife marry', 'come:inf able:neg'], '14:21': ['master of house angry', 'street:pl and narrow street:pl', 'poor person:pl', 'kjv_maimed person:pl', 'kjv_lame person:pl', 'blind person:pl'], '14:22': ['as command', 'yet place'], '14:23': ['highway:pl and hedge:pl', 'compel', 'my/house fill'], '14:24': ['i to you say', 'none of those man:pl', 'my/supper taste'], '14:25': ['great kjv_multitude:pl', 'turn'], '14:26': ['to ipl', 'his/father and mother and wife and child:pl and brother:pl and sister:pl', 'his/own life hate:neg', 'mypl/disciple'], '14:27': ['his/kjv_cross_instrument carry:neg', 'after ipl', 'mypl/disciple'], '14:28': ['kjv_tower build', 'first down sit', 'cost kjv_number', 'enough'], '14:29': ['kjv_foundation lay', 'finish:inf able:neg', 'mock'], '14:30': ['build:inf begin', 'finish:inf able:neg'], '14:31': ['king against another king', 'first down sit', 'ten+thousand', 'twelve+thousand and eight+thousand', 'consider'], '14:32': ['other yet far away', 'messenger:pl', 'condition:pl of peace'], '14:33': ['all that have:pr forsake:neg', 'mypl/disciple'], '14:34': ['salt good', 'his/taste lose', 'kjv_season_food'], '14:35': ['land neither for kjv_dunghill', 'out cast', 'ear:pl', 'hear:opt']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertEqual(cases['13-3']['analysis'],cases['13-5']['analysis'])
  self.assertIn('daughter of kjv_abraham',cases['13-16']['analysis'])
  self.assertIn('i you from where',cases['13-25']['analysis'])
  self.assertIn('wesg in thy/presence',cases['13-26']['analysis'])
  self.assertIn('hen her/young bird:pl',cases['13-34']['analysis'])
  self.assertIn('ass or ox into kjv_pit',cases['14-5']['analysis'])
  self.assertNotIn('son',cases['14-5']['analysis'])
  self.assertIn('honour have:fu',cases['14-10']['analysis'])
  self.assertIn('five yoke:pl of ox:pl',cases['14-19']['analysis'])
  self.assertIn('i to you say',cases['14-24']['analysis'])
  self.assertIn('his/own life hate:neg',cases['14-26']['analysis'])
  self.assertIn('twelve+thousand and eight+thousand',cases['14-31']['analysis'])
  self.assertIn('all that have:pr forsake:neg',cases['14-33']['analysis'])
  self.assertFalse(any(':du' in c['analysis'] for c in cases.values()))
  self.assertEqual(lang.word('kjv_siloam_luke')[0],lang.maxima(lang.lexicon['kjv_siloam_luke']['form']))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),2)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
